\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Exultet iam angelica turba c\u281 elorum, exultent diuina mysteria, et pro tanti regis}}\plain \f1\i\lang1033\fs24   uictoria\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  una cum papa nostro\plain \f1\lang1033\fs24   [Name ausgespart] \plain \f1\i\lang1033\fs24  et gloriosissimo imperatore Luduuico eiusque\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  nobilissima prole\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quiete temporum concessa\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  in his paschalibus conseruare digneris\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Per\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  dominum nostrum Iesum Christum filium tuum\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  qui tecum uiuit et regnat deus in unitate\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  spiritus sancti per omnia secula seculorum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Amen\plain \f1\lang1033\fs24 .
