\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Holzdeckelband}}\plain \f1\lang1033\fs20   mit {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 gr\u252 \'fcnlich-blauem Leder\u252 \'fcberzug}}\plain \f1\lang1033\fs20   (abgenutzt). Spuren von zwei seitlichen Langriemenschlie\u223 \'dfen (Verschl\u252 \'fcsse auf R\u252 \'fcckdeckel); Spuren von f\u252 \'fcnf Metallbeschl\u228 \'e4gen je Deckel; Ketten\u246 \'f6se an Vorderdeckel erhalten. Titelschild auf R\u252 \'fcckdeckel, Pergament, 15. Jh.: \plain \f1\i\lang1033\fs20  Suffragia monachorum\plain \f1\lang1033\fs20  ; dar\u252 \'fcber weiteres Pergamentschildchen unbeschrieben. Titel und Initium auch auf vorderem Spiegel, Pergament, eingetragen, 15. Jh.; dar\u252 \'fcber Papierschild mit Aicher-Signatur 34\u183 \'b76 geklebt. R\u252 \'fcckentitel: \plain \f1\i\lang1033\fs20  Suffragia Monachorum\plain \f1\lang1033\fs20 . \plain \f1\i\lang1033\fs20  S\u230 \'e6c\plain \f1\lang1033\fs20 . \plain \f1\i\lang1033\fs20  XIV\plain \f1\lang1033\fs20 . und -signatur: {\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4650/?u"}{\fldrslt \plain \f1\i\lang1033\fs20\chcbpat17 D. LXII}}\plain \f1\lang1033\fs20 . Vorsatzblatt (I), Pergament, bis auf den {\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17  Schenkungsvermerk}}\plain \f1\lang1033\fs20   (s. unten) leer}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -112\plain \f1\super\lang1033\fs24 va{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17  Suffragia monachorum (Casus legum zu den Dekretalen Gregors IX.)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -37\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Liber I: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pone quedam mulier uolebat lugere maritum suum infra annum}}\plain \f1\lang1033\fs24   \u8230 \'85; \plain \f1\i\lang1033\fs24  Gregorius episcopus\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Quia sicut per seruum domino\plain \f1\lang1033\fs24   (\plain \f1\i\lang1033\fs24  lex\plain \f1\lang1033\fs24  ?) \plain \f1\i\lang1033\fs24  ita per imperatorem hominibus\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  ultra personam extendi non possunt ut ibi dicitur\plain \f1\lang1033\fs24  ; (38\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -60\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Liber II: \plain \f1\i\lang1033\fs24  De Couuldeo\plain \f1\lang1033\fs24   (recte Quouultdeo!) \plain \f1\i\lang1033\fs24  episcopo\plain \f1\lang1033\fs24 . \u8230 \'85; (60\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -84\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Liber III: \plain \f1\i\lang1033\fs24  Ut laici\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Super primis sex decretalibus\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  nulle cadunt leges\plain \f1\lang1033\fs24   \u8230 \'85; (84\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -94\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Liber IV; (85\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Einschub (Wiederholung von zwei Kapiteln aus Liber II): \plain \f1\i\lang1033\fs24  Quia W\plain \f1\lang1033\fs24 . (?) \plain \f1\i\lang1033\fs24  sicut inter eundem P\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  vbi dicitur quod de similibus ad similia\plain \f1\lang1033\fs24   \u8230 \'85; \plain \f1\i\lang1033\fs24  Cum uenissent\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  per iudices\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Quia dicit imperator\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  qui condidit leges\plain \f1\lang1033\fs24   \u8230 \'85; am Rand bei beiden Kapiteln \plain \f1\i\lang1033\fs24  \u248 \'f8\plain \f1\lang1033\fs24  ; (94\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  -112\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Liber V: \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  Sed etsi \u167 \'a7 ult\plain \f1\lang1033\fs24  ; Rest der Seite leer; ab 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   am Rand (etwa gleichzeitig) die betreffenden Tituli der Dekretalen.     
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs20  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Textausz\u252 \'fcge bei M. \plain \f1\scaps\lang1033\fs20 Bertram\plain \f1\lang1033\fs20   u. M. \plain \f1\scaps\lang1033\fs20 Duynstee\plain \f1\lang1033\fs20 , Casus legum sive Suffragia monachorum. Legistische Hilfsmittel f\u252 \'fcr Kanonisten im sp\u228 \'e4teren Mittelalter, in: Tijdschrift voor Rechtsgeschiedenis 51 (1983), S. 317-363, hierzu S. 342 f. und 345-351 (Text 1-9), diese Handschrift bei der Gruppe CL I genannt, S. 336 (zu s. XIV) und 338, aber nicht bei den Textausz\u252 \'fcgen herangezogen; zu Inhalt und Herkunft dieses Rechtstextes vgl. besonders S. 319-321, 324-329}

