\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Homiliae (Rest eines Homiliars)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  In uigilia sancti Laurentii\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  CLV\plain \f1\lang1033\fs24   / \plain \f1\i\lang1033\fs24  Lectio sancti euangelii secundum Math\plain \f1\lang1033\fs24 .< \plain \f1\i\lang1033\fs24  In illo\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  tempore\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  dixit Iesus discipulis suis\plain \f1\lang1033\fs24  ... (Mt 16, 24-28). >\plain \f1\i\lang1033\fs24  Omelia lectionis eiusdem\plain \f1\lang1033\fs24  < (danebenstehend in blassen Majuskeln nachgetragen) \plain \f1\i\lang1033\fs24  Beati Greg\plain \f1\lang1033\fs24  (\plain \f1\i\lang1033\fs24  orii\plain \f1\lang1033\fs24 ). {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gaudeamus}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ,}}\plain \f1\i\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 dilectissimi}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ,}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  gaudio spiritali in beatissimi Christi martyris Laurentii festiuitate}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24 ... \endash ... \plain \f1\i\lang1033\fs24  ut\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  perueniant ad patriam paradysum per dominum nostrum Iesum Christum\plain \f1\lang1033\fs24  ; (3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  In natali\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  sancti Agapiti martyris\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Lectio sancti euangelii secundum Lucam\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  In illo tempore\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Dixit Iesus\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  discipulis suis\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Sint lumbi uestri\plain \f1\lang1033\fs24  ... (Lc 12, 35-40); (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Omelia lectionis eiusdem\plain \f1\lang1033\fs24  < (danebenstehend in blassen Majuskeln nachgetragen) \plain \f1\i\lang1033\fs24  Beati Gregorii papae\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Audistis quomodo dominus discipulos suos ammonuit parare se in aduentum}}\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  adiuuante eodem domino\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  nostro\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24   cui est\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  cum patre et spir\plain \f2\i\lang1024\fs24 itu sancto \u281 \'eaterna potestas et honor et gloria in omnia secula amen\plain \f1\lang1033\fs24  ; darunter Verszeile, 13. Jh. \plain \f1\i\lang1033\fs24  Venite fili\plain \f1\lang1033\fs24   \u8230 \'85 (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia carminum 20109); darunter Angabe der \u220 \'dcberschrift der folgenden Seite (Teil II), sp\u228 \'e4tes 15. Jh.; unten Besitzvermerke, erster unvollst\u228 \'e4ndig, 13. Jh. (?), dann 14. Jh.: \plain \f1\i\lang1033\fs24  Iste liber pertinet ad sanctum Emmerammum Ratispone\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Emmeramme martyr dei preciose\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
