\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -26\plain \f1\super\lang1033\fs24 v\plain \f1\b\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Lectionarium officii (zu den Hauptfesten)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lectiones in festo s. Emmerami: >\plain \f1\i\lang1033\fs24  I {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Exultandum nobis< est hodie dilectissimi et spiritali iocunditate l\u281 \'eatandum}}\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  exultandum filiis\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  in gaudio patris\plain \f1\lang1033\fs24   \u8230 \'85;  (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  II {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nouit autem et ille dominum suum Christum quem amauit}}\plain \f1\lang1033\fs24   \u8230 \'85; (2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  III {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quibus autem uirtutum gradibus Syon istam}}\plain \f1\lang1033\fs24   \u8230 \'85; (3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  IIII {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Ecclesi\u281 \'ea quondam prophetice persuasum fuisse}}\plain \f1\lang1033\fs24   \u8230 \'85; (3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  V {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pro patribus tuis}}\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8230 \'85 (Ps 44, 17). }}{\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Audi mater}}{\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , }}{\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 audi sponsa}}{\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 . }}{\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Pro apostolis qui primo te regebant}}\plain \f1\lang1033\fs24   \u8230 \'85; (4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  VI\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hodie mirabilis illa prophetia uenerandi patris Tobis Iudeis suis}}\plain \f1\lang1033\fs24   \u8230 \'85; (5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  VII {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ardens est igitur in nobis cor nostrum de Iesu et membris eius}}\plain \f1\lang1033\fs24   \u8230 \'85; (6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  VIII {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Et turres Hierusalem gemmis \u281 \'eadificabuntvr, id est propugnatores \u281 \'eacclesi\u281 \'ea}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  et iam si \plain \f2\i\lang1024\fs24 de lapidibus suscitatos multiplicasti sicut stellas c\u281 \'eali et multiplicabis\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Per Christum dominum nostrum\plain \f1\lang1033\fs24  ; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Kirchweihe von St. Emmeram: (8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Acht Lektionen nach Eusebius \lquote Gallicanus\rquote , Homilia XLVII: In natale ecclesiae, I (= Ps.-Augustinus, Sermo 231 und Ps.-Maximus Taurinensis) >\plain \f2\i\lang1024\fs24 In dedicatione ecclesi\u281 \'ea sancti Emmerammi martyris\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24\chcbpat17 Recte festa {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 ecclesi\u281 \'ea}}{\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 colvnt, qvi se}}{\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  >}}{\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 ecclesi\u281 \'ea filios esse cognoscvnt}}\plain \f1\lang1033\fs24  < \u8230 \'85 \endash  \u8230 \'85 \plain \f2\i\lang1024\fs24 Ad qu\u281 \'ea bona \plain \f1\i\lang1033\fs24  uos \plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24  dominus noster Iesus\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  Christus perducat\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  qui eum patre et spiritu sancto uiuit et regnat per omnia secula seculorum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Amen\plain \f1\lang1033\fs24  ; darunter, 15. Jh.: \plain \f1\i\lang1033\fs24  Ewangelium\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Ingressus Ihesus\plain \f1\lang1033\fs24   (Lc 19, 1), \plain \f1\i\lang1033\fs24  respice 1\plain \f1\lang1033\fs24   (Verweis auf vorderen Spiegel); (12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  In illo tempore dixit\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  dominus Iesus discipulis suis\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Non est arbor\plain \f1\lang1033\fs24   \u8230 \'85 (Lc 6, 43-48). >\plain \f1\i\lang1033\fs24  Oratio\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus qui nobis per singulos annos huius sancti templi tui consecrationis}}\plain \f1\lang1033\fs24   \u8230 \'85;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  In sancta nocte P\plain \f2\i\lang1024\fs24 asch\u281 \'ea ad matut\plain \f1\lang1033\fs24 .< Gregorius Magnus, Homiliae in Evangelia XXI (unvollst\u228 \'e4ndig, bis Mitte c. 6) >\plain \f1\i\lang1033\fs24  Lectio sancti evuangelii secvndvm Marcum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  In illo\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  tempore\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Maria Magdalena et Maria\plain \f1\lang1033\fs24   \u8230 \'85 (Mc 16, 1-7). >\plain \f1\i\lang1033\fs24  Om\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  beati Gregorii pape de eadem\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  lectione\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Mvltis uobis lectionibus, fratres karissimi, per dictatum loqui consueui}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  et\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  ostendit exemplo quod nobis promisit in premio\plain \f1\lang1033\fs24  ; in vier Lektionen;  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  In natale sancti Dyonisii martyris\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Lectio prima\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beatus igitur Paulus apostolus per plurima spargens loca uerbi semen diuini uenit etiam ad Athenas causa predicandi}}\plain \f1\lang1033\fs24  ; es folgt Exzerpt aus Hilduinus Sancti Dionysii, Passio s. Dionysii, c. V \endash  IX (Anfang), XII (Schlu\u223 \'dfteil fehlt): \plain \f2\i\lang1024\fs24 Cum autem uocis novitate Ath\u281 \'eaniensis permoti\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quadam\plain \f1\lang1033\fs24    \u8230 \'85 \endash  (21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24  id est de ordinibvs angelorum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Epithoma etiam eidem Tymotheo composuit\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  sed profundissimis\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  uerbis eiusdem apostoli scriptis suis ea inserendo definiuit\plain \f1\lang1033\fs24  ; (21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Secundum\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  Matheum\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  In illo tempore dixit Ihesus discipulis suis\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Ecce ego mitto\plain \f1\lang1033\fs24   \u8230 \'85 (Mt 10, 16, Text von Mt 10, 16-22 auf 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ); (21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) es folgt Exzerpt aus Ambrosius Mediolanensis, Expositio Evangelii secundum Lucam, VII, 46, 47 (beide unvollst\u228 \'e4ndig), 48-51 (Schlu\u223 \'df fehlt): >\plain \f1\i\lang1033\fs24  Omelia\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  beati Ambrosii episcopi\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Contraria sibi sunt ista animalia, ut alia ab aliis}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  Caue igitur\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  uersute disputationis uenena\plain \f1\lang1033\fs24 .\~\plain \f1\i\lang1033\fs24  L\plain \f1\lang1033\fs24 .; Passio und Homilia in zw\u246 \'f6lf Lesungen; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (24\plain \f1\super\lang1033\fs24 r/v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Cap\plain \f1\lang1033\fs24 .< \plain \f1\i\lang1033\fs24  Benedictus deus et pater\plain \f1\lang1033\fs24   \u8230 \'85 (I Pt 1, 3); >\plain \f1\i\lang1033\fs24  Or\plain \f1\lang1033\fs24 .< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus qui hodierna die beatum Dyonisium martyrem tuum atque pontificem}}\plain \f1\lang1033\fs24   \u8230 \'85 \plain \f1\i\lang1033\fs24  et nulla eius aduersa formidare\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Per\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24  Dominica XV\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs24  <; \plain \f1\i\lang1033\fs24  Ecclesiam tuam\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  domine\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  miseratio continuata mundet\plain \f1\lang1033\fs24   \u8230 \'85 \plain \f1\i\lang1033\fs24  munere\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  gubernetur\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Per\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24  Dominica XVI\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs24  <; \plain \f1\i\lang1033\fs24  Tua nos\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  domine\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quesumus gratia semper et preueniat\plain \f1\lang1033\fs24   \u8230 \'85 \plain \f1\i\lang1033\fs24  prestet esse intentos\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Per\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24  Dominica XVII\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs24  <; \plain \f1\i\lang1033\fs24  Da\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quesumus\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  domine\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  populo tuo diabolica\plain \f1\lang1033\fs24   \u8230 \'85 \plain \f1\i\lang1033\fs24  pura mente sectari\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Per\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24  Dominica XVIII\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs24  <;
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Gregorius Magnus, Homiliae in Evangelia XXX, 1-3 (Text abgebrochen): >\plain \f1\i\lang1033\fs24  In sancta nocte Pent\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Lectio sancti ewangelii secundum Iohannem\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  In illo tempore\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  dixit dominus Ihesus discipulis suis\plain \f1\lang1033\fs24 :< \plain \f1\i\lang1033\fs24  Si quis diligit me\plain \f1\lang1033\fs24   \u8230 \'85 (Io 14, 23-31). >\plain \f1\i\lang1033\fs24  Omelia beati\plain \f1\lang1033\fs24   \plain \f2\i\lang1024\fs24 Gregorii pape de \u281 \'eaadem lectione\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Libet, fratres karissimi, euangelic\u281 e uerba lectionis sub breuitate transcurrere}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f2\i\lang1024\fs24 et suggeret uobis omnia qu\u281 \'eacumque dixero uo\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  //; drei Lektionen bis zum Abbruch des Textes.  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20                         
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Druck/Edition\plain \f1\scaps\lang1033\fs20 : \plain \f1\lang1033\fs20  Die ersten vier Lektionen bei D. \plain \f1\scaps\lang1033\fs20 Hiley\plain \f1\lang1033\fs20 , Historia Sancti Emmerammi Arnoldi Vohburgensis ca. 1030. Einf\u252 \'fchrung und Edition. Ottawa 1996 (Wissenschaftliche Abhandlungen 65/2), S. 41 f. Appendix II nach Clm 14872 in acht Lesungen gedruckt (vgl. ebd. S. xvi und \plain \f1\scaps\lang1033\fs20 Bischoff\plain \f1\lang1033\fs20 , Literarisches und k\u252 \'fcnstlerisches Leben, S. 85 mit Anm. 43); Eusebius \lquote Gallicanus\rquote , Homilia XLVII in CCL 101A, S. 555-563 (vgl. CPPM IA, 1016; CPPM IB, 4664, 5952); Oratio (12\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) in P. \plain \f1\scaps\lang1033\fs20 Bruylants\plain \f1\lang1033\fs20 , Les oraisons du Missel Romain II, Louvain 1952 (\u201 \'c9tudes liturgiques 1), S. 107 Nr. 392; Gregorius Magnus, Homilia XXI in CCL 141, S. 173-177; Passio s. Dionysii in PL 106, Sp. 26-29, 31 f. (BHL 2175); vgl. dazu auch R. \plain \f1\scaps\lang1033\fs20 Hankeln\plain \f1\lang1033\fs20 , Historiae sancti Dionysii Areopagitae. Ottawa 1998 (Wissenschaftliche Abhandlungen 65/3), S. xxvii f.; Ambrosiusexzerpt in CCL 14, S. 229-231; Gebete (24\plain \f1\super\lang1033\fs20 r/v\plain \f1\lang1033\fs20 ) in J. \plain \f1\scaps\lang1033\fs20 Deshusses\plain \f1\lang1033\fs20 , Le sacramentaire gr\u233 \'e9gorien II. Fribourg/Suisse 1979 (Spicilegium Friburgense 24), S. 328 Nr. 3636; \plain \f1\scaps\lang1033\fs20 Bruylants\plain \f1\lang1033\fs20 , Les oraisons II, S. 141 Nr. 521, S. 335 Nr. 1150, S. 57 Nr. 183; Gregorius Magnus, Homilia XXX in CCL 141, S. 255-258}

