\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) // \plain \f1\i\lang1033\fs24  qui uero\plain \f1\lang1033\fs24   \lquote \plain \f1\i\lang1033\fs24  ex theatro\plain \f1\lang1033\fs24  \rquote  \plain \f1\i\lang1033\fs24  se uenire dicit \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24  quae male coniuncta separet\plain \f1\lang1033\fs24   //; (18\plain \f1\super\lang1033\fs24 r/v\plain \f1\lang1033\fs24 ) // \plain \f1\i\lang1033\fs24  promiscue uocantur\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Gula dicendum non gyla\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  ut\plain \f1\lang1033\fs24   \lquote \plain \f1\i\lang1033\fs24  benedicta tu\plain \f1\lang1033\fs24  ...\rquote // (19\plain \f1\super\lang1033\fs24 r/v\plain \f1\lang1033\fs24 ) // \plain \f1\i\lang1033\fs24  Nubit\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  quia pallio\plain \f1\lang1033\fs24  ... \endash ... \plain \f1\i\lang1033\fs24  Prouerbium latine\plain \f1\lang1033\fs24   //.
