\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Exzerpte moralisch-aszetischen Inhalts aus Kirchenv\u228 \'e4tern und Altem Testament (Prv, Ecl, Sir)}}\plain \f1\lang1033\fs24     
