\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24  De sancto Egidio\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Sanctvs igitur Egidivs natione Grecorum a claris parentibus originem\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  duxit\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f2\i\lang1024\fs24 Qu\u281 \'ea diligentius indagando sequentes\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  peruenerunt\plain \f1\lang1033\fs24   //; Rest der Seite leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 4\plain \f1\super\lang1033\fs24 r/v\plain \f1\lang1033\fs24   unbeschrieben.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
