\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -8\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Meditationes in Psalmos 1 \endash  11}}\plain \f1\b\lang1033\fs24     
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (5\plain \f1\super\lang1033\fs24 ra/b\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Qvi abiit\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  stetit et sedit \plain \f1\lang1033\fs24  (vgl. Ps 1, 1). \plain \f1\i\lang1033\fs24  Ecce filius fa.\plain \f1\lang1033\fs24  (?), \plain \f2\i\lang1024\fs24 qui petiit partem substanti\u281 \'ea su\u281 \'ea \plain \f1\i\lang1033\fs24  uolens se\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  ipsum sine alio regere\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  Pro eo dico ut non roget quis\plain \f1\lang1033\fs24  ; (5\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  -5\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ego autem constitutus sum rex ab eo de quo dicitur: Egredimini fili\u281 e Ierusalem \u8230 \'85 (Ct 3, 11)}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  Ad tercium\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  diadema pertingatis\plain \f1\lang1033\fs24  ; (5\plain \f1\super\lang1033\fs24 va/b\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domine quid multiplicati \u8230 \'85 (Ps 3, 2). Conqueritur siquidem ratio de sensualitatis dominio}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  sensu nutu uoluntatis sentit contra rationem\plain \f1\lang1033\fs24  ; (5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  -6\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Signatum est \u8230 \'85 (Ps 4, 7). Non dicitur uultus signatus sed lumen uultus signatum}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Trinitas \plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  de quo dicit propheta\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Signatum est super\plain \f1\lang1033\fs24   \u8230 \'85 (Ps 4, 7); (6\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Uerba mea \u8230 \'85 (Ps 5, 2). Ecce \u281 \'eacclesia triplicem thesaurum offerens}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  contra impietatem sinceritate corporali\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  contra impudicum\plain \f1\lang1033\fs24  ; (6\plain \f1\super\lang1033\fs24 ra/b\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Domine ne in furore \u8230 \'85 (Ps 6, 2). Hic furor et hec ita et quam timet p\u281 \'eanitens}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  Vnde psalmista\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Beati quorum re\plain \f1\lang1033\fs24  ; (6\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  -6\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Exurge domine \u8230 \'85 (Ps 7, 7). Ecce ad patientiam et humilitatem inuitat nos propheta exemplo Christi}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f2\i\lang1024\fs24 Medicina sit adhibita equitatis et iustici\u281 \'ea\plain \f1\lang1033\fs24  ; (6\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  -7\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnia subiecisti \u8230 \'85 (Ps 8, 8). De his ouibus alias dicitur}}\plain \f1\lang1033\fs24  ... \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  sicut canis suo domino\plain \f1\lang1033\fs24  ; (7\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -7\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dixit enim in corde \u8230 \'85 (Ps 9, 27). De isto dicitur a Iacob in benedictionibus filiorum}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  quia plus omnibus malis\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  fideles decepit\plain \f1\lang1033\fs24  ; (7\plain \f1\super\lang1033\fs24 va/b\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Contere brachium peccatoris \u8230 \'85 (Ps 9, 36). Erit enim tunc tribulatio magna, ut ait dominus in euangelio}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  et potus mellis siluestris\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  nimia parcitate\plain \f1\lang1033\fs24  ; (7\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  -8\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Transmigra in montem \u8230 \'85 (Ps 10, 2). Christus quidem dicitur mons iuxta illud Ysaie}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  ad eminentiam nostri intellectus\plain \f1\lang1033\fs24  ; (8\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  -8\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 Probatum terr\u281 \'ea purgatum}}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 septuplum}}\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 (Ps 11, 7), }}{\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 id est per septem dona sancti spiritus}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  quibus ad totidem gradus\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  beatitudinis ascendimvs}

