\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  62\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -64\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tonar}}
