\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Boethius}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Commentaria in Ciceronis Topica}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u220 \'dcberschriften (im 11. Jh. von wohl zwei H\u228 \'e4nden nachgetragen im freien oberen Drittel der Seite mit Spuren von Rasur): \plain \f1\i\lang1033\fs24  Incipit commentum\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  in Topica\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Anicii Severini Boetii viri\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  consvlaris et inlvstris ex cons\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  ordine ad patricivm in Topica Marcii Tvllii Ciceronis\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  commentariorum liber primus incipit\plain \f1\lang1033\fs24  ; Kommentar: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Exhortatione tva}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  [nachgetragen], }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Patrici}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ,}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  rethorum peritissime}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ,}}\plain \f2\i\lang1024\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\i\lang1024\fs24\chcbpat17 qu\u281 \'ea et pr\u281 \'easentis honestate propositi}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  (27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24  et ad ampliora huius\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  operis festinamvs\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Incipit tractatvs\plain \f1\lang1033\fs24 . [C]\plain \f1\i\lang1033\fs24  vm omnis racio diligens disserendi duas habeat partes\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f2\i\lang1024\fs24 qu\u281 \'ea concurrentia \plain \f1\i\lang1033\fs24  fidem facerent proditionis\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Talis etiam fortuitarvm rervm\plain \f1\lang1033\fs24  ; Rest der Seite leer, 93\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  ebenfalls; 54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   bis auf erste Zeile leer (wohl wegen zu d\u252 \'fcnnem Pergament).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
