\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24  Incipiunt sermones defunctorum\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  de diuersis personis\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Memor esto iudicii \u8230 \'85 (Sir 38, 23). Nota quod ista est differentia inter statuta dei et statuta hominum}}\plain \f1\lang1033\fs24   \u8230 \'85; (132\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Jacobus de Voragine: \plain \f1\i\lang1033\fs24  Memor esto iudicii\plain \f1\lang1033\fs24   \u8230 \'85 (Sir 38, 23). \plain \f1\i\lang1033\fs24  Recte mortuus vitam\plain \f1\lang1033\fs24   (!) \plain \f1\i\lang1033\fs24  ad memoriam mortem\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  reducit\plain \f1\lang1033\fs24   \u8230 \'85; \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 3, S. 264 Nr. 576; (133\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Sermo unius defunctorum\plain \f1\lang1033\fs24  ; \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 7, S. 492 Nr. 125; (133\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Jacobus de Voragine: \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 3, S. 264 Nr. 579; (134\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Nr. 580; (134\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) S. 265 Nr. 581; (135\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sancta et salubris \u8230 \'85 (II Mcc 12, 46). Viventes circa mortuos tria debent facere}}\plain \f1\lang1033\fs24   \u8230 \'85; wie Uppsala, UB, C 279, 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; (136\plain \f1\super\lang1033\fs24 rb\plain \f2\lang1024\fs24 ) Johannes Mili\u269 \'e8: \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 3, S. 599 Nr. 235; (139\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Sermo qui potest fieri in alicuius venerabilis\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  patris videlicet pape\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  patriarche\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  archiepiscopi\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  qui elegit sibi sepulturam in aliquo foco \plain \f1\lang1033\fs24  (lies\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  loco) \plain \f1\i\lang1033\fs24  religioso et predicato\plain \f1\lang1033\fs24   (lies predicator), \plain \f1\i\lang1033\fs24  qui predicat\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  dicit sic\plain \f1\lang1033\fs24  <; vgl. N\u252 \'fcrnberg, GNM, Hs 27888, 273\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  ; Bertrandus de Turre, Sermones de mortuis: \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 1, S. 579 Nr. 1080; (139\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) S. 577 Nr. 1058 (140\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  /141\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) S. 579 Nr. 1078; (142\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Nr. 1082; (142\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) S. 582 Nr. 1120; (143\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) S. 581 Nr. 1100; (145\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) S. 579 Nr. 1081; (145\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iustus de angustia \u8230 \'85 (Prv 11,8). In quo quidem verbo breviter tria innuntur}}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Primo\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  securitas\plain \f1\lang1033\fs24   \u8230 \'85; (146\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) S. 582 Nr. 1117; (147\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) S. 577 Nr. 1052; (148\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Melior est mors \u8230 \'85 (Sir 30,17). In quo quidem verbo sapiens ecclesiasticus iustorum hominum mortem}}\plain \f1\lang1033\fs24   \u8230 \'85; (149\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Timenti deum bene \u8230 \'85 (Sir 1,13). Iste moritur robustus \u8230 \'85 (Iob 21,23). Istud verbum potest exponi satis congrue in exequiis istius viri nobilis iuuenis}}\plain \f1\lang1033\fs24   \u8230 \'85; wie N\u252 \'fcrnberg, GNM, Hs 27888, 290\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  ; (149\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Convenit ecclesia magna \u8230 \'85 (I Mcc 5, 16). Quando aliquis tenetur in captivitate}}\plain \f1\lang1033\fs24   \u8230 \'85; wie Uppsala, UB, C 343, 188\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ; (150\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nota quando duo vnum simul portant magnum pondus utique leue videtur esse}}\plain \f1\lang1033\fs24   \u8230 \'85; (150\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beati mortui \u8230 \'85 (Apc 14,13). Exemplo inde Machabei: Qui XII milia dragmas argenti \u8230 \'85 (II Mcc 12,43). Fideles catholici orant hodie pro fidelibus defunctis}}\plain \f1\lang1033\fs24   \u8230 \'85; (151\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Mortuo prebe auxilium}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 , }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 mortuo fac misericordiam}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  (?). }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ecci}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 . }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 IIII}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs24\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 . }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ysidorus libro III}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs24\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  de summo bono dicit}}\plain \f1\lang1033\fs24\chcbpat17 , {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 quod amicus}}\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24  Rogemus ergo surgentes pro animabus\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  pro animabus fidelium defunctorum\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24  ut dominus deus det eis requiem eternam et lux perpetua luceat eis\plain \f1\lang1033\fs24 .               \plain \f1\l