\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 De sancto Stephano protomartyre: (14\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) 327, (15\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) 328; (16\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De eodem< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum autem esset Stephanus plenus}}\plain \f1\lang1033\fs24\chcbpat17  \u8230 \'85 (Act 7,55). {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quinque de}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 causis intendit celum}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Prima ut referet deo\plain \f1\lang1033\fs24   \u8230 \'85 (Initium wie Augsburg, UB, Cod. II.1.2\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs24   5, 157\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ); >\plain \f1\i\lang1033\fs24  De eodem\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Stephanus plenus gratia et fortitudine (Act 6,8). 4o enim habuit plenitudines id est perfecciones}}\plain \f1\lang1033\fs24   \u8230 \'85; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 De sancto Johanne apostolo: (16\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) 332 (Schlu\u223 \'df abweichend), (17\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) 334; (18\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De eodem\plain \f1\lang1033\fs24  <{\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Veniat dilectus \u8230 \'85 (Ct 5,1). Dulcis inuitatio propter dilectum}}\plain \f1\i\lang1033\fs24   qui hic\plain \f1\lang1033\fs24   (?) \plain \f1\i\lang1033\fs24  invitatur ibi veniat\plain \f1\lang1033\fs24   \u8230 \'85 (Initium vgl. \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 1, S. 208 Nr. 780, zu Aldobrandinus Cavalcanti); (19\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De eodem\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Qui timet deum faciet bona. Ecc. (Sir 15,1; vgl. Sir 6,17).\~In verbis istis duo facit: Primo timorem virtuosum specificat}}\plain \f1\lang1033\fs24   \u8230 \'85 (Initium und Schlu\u223 \'df wie \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 7, S. 486 Nr. 57); De Innocentibus: (19\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) 335 (Schlu\u223 \'df abweichend); (20\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De eodem sermo\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vidi supra montem \u8230 \'85 et cum eo 100 44 milia (Apc 14,1). Duodecies 14 (? lies duodecim) faciunt centum 44. Nota per centum 44 milia significantur}}\plain \f1\i\lang1033\fs24   omnes illi\plain \f1\lang1033\fs24   \u8230 \'85 (Initium vgl. Herzogenburg, Stiftsbibl., Cod. 59, fol. 125 sowie \plain \f