\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (4\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -5\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De protestationibus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  >\plain \f1\i\lang1033\fs24  De protestacionibus\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  In nomine etc. ... venerabilibus viris  dominis V. preposito sancti ... electo in episcopum ecclesie ... ac P. archiepiscopi\plain \f1\lang1033\fs24   (!)\plain \f1\i\lang1033\fs24   ac canonici\plain \f1\lang1033\fs24   (!)\plain \f1\i\lang1033\fs24   eiusdem ecclesie cum institucionibus eleccionis\plain \f1\lang1033\fs24  ... (4\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Protestacio ad portam pape causa eleccionis abbatis\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  In nomine etc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Personaliter constitutus religiosus vir frater A. monachus monasterii ... existens ante primam portam palacii domini nostri pape}}\plain \f1\i\lang1033\fs24 , per quam communis habetur introitus\plain \f1\lang1033\fs24  ... (5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Protestacio ad uisitandum limina apostolorum\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  In nomine etc. Vt supra. Quia valebat procuracio nomine dicti domini episcopi se coram eo presentare et ipsum dominum papam et limina apostolorum et sedem apostolicam visitare\plain \f1\lang1033\fs24  ... >\plain \f1\i\lang1033\fs24  Super eodem coram camerario pape\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  In nomine etc. Constitutus coram reuerendissimo p\plain \f1\lang1033\fs24  [\plain \f1\i\lang1033\fs24  atre\plain \f1\lang1033\fs24  ]\plain \f1\i\lang1033\fs24   in Christo domino A. archiepiscopo Auxitano \plain \f1\lang1033\fs24  (Auch) \plain \f1\i\lang1033\fs24  sedis apostolice camerario dicit, quod dictus dominus episcopus propter quedam negocia\plain \f1\lang1033\fs24  ... >\plain \f1\i\lang1033\fs24  Protestacio quot si ecclesia collata tibi non debeatur tibi non preiudicet\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  In nomine etc. Cum reuerendissimus in Christo pater dominus cardinalis contulisset venerabilem virum\plain \f1\lang1033\fs24  ...-... (5\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  aliter canonice conferantur. Super quibus etc\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (5\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  -5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ){\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  Litterae episcopales de synodo et de visitatione}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  >\plain \f1\i\lang1033\fs24  Qualiter episcopus vocat ad synodum clericos sue diocesis\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Arnoldus etc. omnibus et singulis abbatibus, prioribus ... {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum nostram generalem synodum bis in anno per nos aut vnum de vicarijs nostris}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  ... (5\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Qualiter episcopus procedit contra clericum non venientem ad synodum\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Arnoldus etc. Cum ... rector ecclesie ... vocatus et inventus fuisset\plain \f1\lang1033\fs24  ... (in Teilen \u228 \'e4hnlich \plain \f1\scaps\lang1033\fs24 Dominicus Dominici, Summa dictaminis\plain \f1\lang1033\fs24 , Ed.: \plain \f1\scaps\lang1033\fs24 Rockinger\plain \f1\lang1033\fs24 , Briefsteller, S. 551, Nr. 40). >\plain \f1\i\lang1033\fs24  Quomodo episcopus habet aliquem excusatum quia non venit in synodum etc.\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Arnoldus etc\plain \f1\lang1033\fs24 .\plain \f1\i\lang1033\fs24   Rectori ... Recepimus vestras litteras continentes, quod cum vos quodam\plain \f1\lang1033\fs24   (!)\plain \f1\i\lang1033\fs24   instanti et vrgenti necessitate impeditus\plain \f1\lang1033\fs24  ...-... (5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  protinus ordinauimus. Datum etc\plain \f1\lang1033\fs24 . (vgl. \plain \f1\scaps\lang1033\fs24 Dominicus Dominici, Summa dictaminis\plain \f1\lang1033\fs24 , Ed.: \plain \f1\scaps\lang1033\fs24 Rockinger\plain \f1\lang1033\fs24 , Briefsteller, S. 551f., Nr. 41.- Krakau BJ, Cod. 461, 112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). >\plain \f1\i\lang1033\fs24  Quando episcopus habeat visitare\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Arnoldus etc. Dilecto filio nostro rectori ... Noueritis quod nos die ... de mane domino concedente vestram intendimus ecclesiam personaliter visitare\plain \f1\lang1033\fs24  ... (vgl.\plain \f1\scaps\lang1033\fs24  Dominicus Dominici, Summa dictaminis\plain \f1\lang1033\fs24 , Ed.: \plain \f1\scaps\lang1033\fs24 Rockinger\plain \f1\lang1033\fs24 , Briefsteller, S. 562, Nr. 67). >\plain \f1\i\lang1033\fs24  Item episcopus quomodo significat rectoribus quod debet visitare\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Salutem. Cum ex debito nostri teneamur officii vestram diocesem visitare\plain \f1\lang1033\fs24  ...-... \plain \f1\i\lang1033\fs24  conferre \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24   presumatis\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  -9\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De commissionibus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  >\plain \f1\i\lang1033\fs24  De commissionibus. Commissio execucionem mandati apostolici\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Arnoldus etc. Executor cum arbitriis certis nostris super transscripta gracia per litteras apostolicas deputatus venerabilibus et discretis viris ... salutem in domino. Sanctissimus in Christo pater etc. Imperfecta\plain \f1\lang1033\fs24   (dar\u252 \'fcber: \plain \f1\i\lang1033\fs24  in gratia\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  clerico diocesis per litteras appostolicas nobis executoribus \plain \f1\lang1033\fs24  (?) \plain \f1\i\lang1033\fs24  nostris\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  prouideri mandauit\plain \f1\lang1033\fs24  ... (6\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Commissio per modum processus\plain \f1\lang1033\fs24  ...< \plain \f1\i\lang1033\fs24  Petrus etc. Executor ad infrascripta in forma vna cum infra scriptis collegis ... salutem in domino et mandatis nostris ... obedienciam. Litteras sanctissimi in Christo patris etc. infra in processibus forme pauperum \plain \f1\lang1033\fs24 ... (6\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Commissio vicariatus a cardinali concessa\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Anglicus\plain \f1\lang1033\fs24   (wohl Anglicus Grimoardi, unter Urban V. Bischof von Avignon, Kardinal; Titularkirche: S. Petri ad Vincula; s.a. 6\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 .- Vgl. Marie-Hyacinthe \plain \f1\scaps\lang1033\fs24 Laurent\plain \f1\lang1033\fs24   u.a. (Hrsg.): Lettres communes des papes du XIV\plain \f1\super\lang1033\fs24 e\plain \f1\lang1033\fs24   si\u232 \'e8cle. Urbain V. (1362-1370), Bd. 1-12, Rom u.a. 1954-1989, Register s.v. Anglicus Grimoardi),\plain \f1\i\lang1033\fs24   miseracione diuina ... ecclesiis sanctorum Petri et Pauli, qui tituli nostri cardinalatus exiit oculos spiritualis deuocionis dirigimus et cupimus\plain \f1\lang1033\fs24  ...
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (9\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Super eodem\plain \f1\lang1033\fs24  < \plain \f1\i\lang1033\fs24  Ludovicus etc. dilecto suo P. canonico baccalaureo in decretis salutem in domino. Vniversitatem causarum, quas apud ... nostre diocesis occurrere contingerit\plain \f1\lang1033\fs24  ... (vgl.\plain \f1\scaps\lang1033\fs24  Dominicus Dominici, Summa dictaminis\plain \f1\lang1033\fs24 , Ed.: \plain \f1\scaps\lang1033\fs24 Rockinger\plain \f1\lang1033\fs24 , Briefsteller, S. 556, Nr. 53). }

