\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  126\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -155\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones de communi sanctorum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (126\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -137\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Conradus de Brundelsheim}}\plain \f1\lang1033\fs24   (Soccus), Sermones de sanctis (hier dem Commune sanctorum zugeordnet): {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Uos estis \u8230 \'85 (Lc 22,28). Idem ut supra dicit Gregorius: Quod valde ex dolore reportabile (?) ostenditur}}\plain \f1\i\lang1033\fs24   ex provida consideracione remuneracionis leuigatur\plain \f1\lang1033\fs24   \u8230 \'85  \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Rep. 1, S. 743 f. Nr. 342; (127\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Sermo de apostolis\plain \f1\lang1033\fs24  < S. 739 Nr. 287; (129\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De martiribus\plain \f1\lang1033\fs24  < S. 739 Nr. 282; (130\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Alius sermo de martiribus\plain \f1\lang1033\fs24  < S. 745 Nr. 357; (131\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  vno martyre\plain \f1\lang1033\fs24  < Nr. 283; (133\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Ordines\plain \f1\lang1033\fs24 . Nr. 280 (anderer Schlu\u223 \'df); (134\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  una virgine\plain \f1\lang1033\fs24  < Nr. 281 (anderer Schlu\u223 \'df); (135\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Sermo alius de vna virgine\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Vtique bonus\plain \f1\lang1033\fs24  < S. 740 Nr. 295; 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (137\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ego vos elegi \u8230 \'85 (Io 15,16). Quanto fructus magis dulcis et permanens}}\plain \f1\i\lang1033\fs24   tanto est\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  magis laborandum et insistendum\plain \f1\lang1033\fs24   \u8230 \'85 (wie Augsburg, UB, Cod. II.1.2\plain \f1\super\lang1033\fs24 o\plain \f1\lang1033\fs24   141, 301\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ); (140\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Sermo de vno martire\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Probatus est in illo et perfectus inventus est. Ita scribitur Ecc. 31 (Sir 31,10). Et sumitur de quadam leccione, que in officio misse de vno martire legitur}}\plain \f1\lang1033\fs24   \u8230 \'85; (141\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De vno\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  martire alius sermo\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gloriosam mortem \u8230 \'85 (II Mcc 6,19). Licet verbum istud de Eleazaro homine magnanimo et constantissimo}}\plain \f1\lang1033\fs24   \u8230 \'85; (143\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De martiribus\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beati qui persecutionem \u8230 \'85 (Mt 5,10). Et legitur de martiribus Macrobius super sompno Scipionis libro primo}}\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24  \u8230 \'85; (145\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Reddet deus \u8230 \'85 (Sap 10,17). Labor magnus eximius mercedem magnam re}}\plain \f1\i\lang1033\fs24  quirit\plain \f1\lang1033\fs24    \u8230 \'85; (148\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Sermo de vno confessore et doctore\plain \f1\lang1033\fs24  <  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In medio ecclesie}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  \u8230 \'85 (Sir 15,5). }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vacuum natura non admittit etc}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 . }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ut supra}}\plain \f1\lang1033\fs24\chcbpat17 . {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quare supra}}\plain \f1\lang1033\fs24   \u8230 \'85; (149\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De simplici confessore sermo\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 De omni corde \u8230 \'85 Ita scribitur Ecc. 47 (Sir 47,10). Tunc enim deum perfectum laudamus}}\plain \f1\lang1033\fs24   \u8230 \'85; (151\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  De virginibus et primo de una virgine\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Despondi vos \u8230 \'85 (II Cor 11,2). Quando virgo aliqua vni viro nobili et potenti et diuiti est copulata et desponsata}}\plain \f1\lang1033\fs24   \u8230 \'85; (153\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -155\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24  Item de vna virgine\plain \f1\lang1033\fs24  < {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Que parate \u8230 \'85 (Mt 25,10). Et sumitur de ewangelio quod de virginibus legitur}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  Virgines ad nuptias dignissimas et excellentissimas\plain \f1\lang1033\fs24   \u8230 \'85 \endash  \u8230 \'85 abgesetzt \plain \f1\i\lang1033\fs24  Et sic est finis\plain \f1\lang1033\fs24  ; Rest der Spalte leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Druck der Sermones de Sanctis von Conradus de Brundelsheim Stra\u223 \'dfburg 1484 (GW 7413; BSB-Ink C-518) Nrr. LXXVI, XXI, XVI, XCI, XVII, XIIII, XV, XXIX. \endash  Zwei Initien (126\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 , 137\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 ) bei \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Wegweiser, S. 543, 213.}

