\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 4. 55\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 -56\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Passio s. Sigismundi}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 >\plain \f1\i\lang1033\fs24\cf1 P\plain \f1\lang1033\fs24\cf1 [assio san]\plain \f1\i\lang1033\fs24\cf1 cti Sigism\plain \f1\lang1033\fs24\cf1 [undi] \plain \f1\i\lang1033\fs24\cf1 regis et martyris\plain \f1\lang1033\fs24\cf1 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 [T]emporibus Tyberii senatoris augusti qui sicut reliquas regiones ita Gallias et Ausoniam regebat}}\plain \f1\i\lang1033\fs24\cf1  egressa est gens de insula \plain \f1\lang1033\fs24\cf1 \u8230 \'85 \endash  \u8230 \'85\plain \f1\i\lang1033\fs24\cf1  adiuuante domino nostro Jhesu Christo etc. - Explicit passio sancti Sigismundi etc.  amen.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 
